package slug

import "strings"

// Slugify lowercases s and replaces spaces with '-', keeping every other character.
func Slugify(s string) string {
	lower := strings.ToLower(s)
	return strings.Map(func(r rune) rune {
		if r == ' ' {
			return '-'
		}
		return r
	}, lower)
}

