package slug

import (
	"strings"
	"unicode"
)

// Slugify lowercases s, collapses runs of whitespace into a single '_',
// and drops every character that is not a letter, digit, or '_'.
func Slugify(s string) string {
	lower := strings.ToLower(s)

	var b strings.Builder
	inSpace := false
	for _, r := range lower {
		if unicode.IsSpace(r) {
			if !inSpace {
				b.WriteByte('_')
				inSpace = true
			}
			continue
		}
		inSpace = false
		if r == '_' || unicode.IsLetter(r) || unicode.IsDigit(r) {
			b.WriteRune(r)
		}
	}
	return b.String()
}

